('sofer-inchiriere','en','82','082','What is the role of the differential?','[{"key":"a","text":"allows interruption of power flow transmission"},{"key":"b","text":"allows progressive coupling of the engine with the transmission"},{"key":"c","text":"distributes engine torque to the drive wheels"},{"key":"d","text":"protects the transmission from shocks and overloads"}]','c','[]'),
('sofer-inchiriere','en','83','083','What is the role of the differential?','[{"key":"a","text":"allows interruption of power flow transmission"},{"key":"b","text":"allows progressive coupling of the engine with the transmission"},{"key":"c","text":"allows the drive wheels to run at different speeds"},{"key":"d","text":"protects the transmission from shocks and overloads"}]','c','[]'),
