('sofer-inchiriere','en','160','160','What is the maximum working time per week:','[{"key":"a","text":"36 hours"},{"key":"b","text":"40 hours"},{"key":"c","text":"48 hours"},{"key":"d","text":"50 hours"}]','c','[]'),
('sofer-inchiriere','en','161','161','What are the main sanctions?','[{"key":"a","text":"confiscation of the vehicle"},{"key":"b","text":"prison"},{"key":"c","text":"the warning and the fine"},{"key":"d","text":"vehicle immobilization"}]','c','[]'),
